const r=require('./round-fixes.js');
const A=q=>r.verifiedRoundAnswer(r.normalizeQuestion(q),{});
const yes=[
['協會地址改了章程也要改嗎','換地址要不要改章程'],['地址變更要不要改章程','換地址要不要改章程'],['搬家章程要改嗎','換地址要不要改章程'],
['搬家要先開理事會嗎','搬家要不要先開理事會'],
['會址是租的可以嗎','租來或借來'],
['地址變了公文怎麼寫','書表下載'],
['理事會可以決定改章程嗎','理事會不能自己改'],['章程要改，理事會同意就好嗎','理事會不能自己改'],
['章程修改要開會員大會嗎','要，出席人數三分之二'],['章程要大會通過才算嗎','要，出席人數三分之二'],['章程改了要經過大會通過嗎','要，出席人數三分之二'],
['章程可以自己隨便改嗎','錯字也要走'],['章程有錯字可以直接改嗎','錯字也要走'],['章程打錯字要重新開會嗎','錯字也要走'],
['會員大會不同意改章程怎麼辦','沒通過章程修改案'],
['章程改好了要報給誰','報縣府'],['章程修正要送哪裡','報縣府'],
['章程送出去要多久核准','沒有寫縣府的處理天數'],['縣府核備章程要等多久','沒有寫縣府的處理天數'],
['章程可以加入罰款規定嗎','罰款或罰則'],['章程能寫會員違規罰錢嗎','罰款或罰則'],['章程可以訂罰則嗎','罰款或罰則'],
['協會名稱可以改嗎','名稱可以改嗎'],['可以換協會名稱嗎','名稱可以改嗎'],
];
const no=['開會地點一定要在會址嗎','會址一定要租嗎','章程可以把理事長任期改成不限次數嗎','章程修改要開理事會嗎','會所搬家章程要改嗎','章程是誰決定可以改的','合作社章程可以改嗎','公會章程修改要開大會嗎','協會名稱不能和別人一樣嗎','協會名稱重複怎麼辦','社區發展協會改名可以嗎','理事會可以決定預算嗎','搬家要多久內報縣府','理事長家裡可以當會址嗎','章程要寫哪些東西','會員退會要經理事會同意嗎','協會成立要先開籌備會嗎','大會沒過半怎麼辦'];
const pat=/換地址要不要改章程|搬家要不要先開理事會|租來或借來|書表下載|理事會不能自己改|要，出席人數三分之二|錯字也要走|沒通過章程修改案|報縣府，30 日|沒有寫縣府的處理天數|罰款或罰則|名稱可以改嗎/;
let bad=0;
for(const [q,k] of yes){const x=A(q);if(!x||!x.direct||!(x.summary+x.title).includes(k)){console.error('FAIL',q,x&&x.title);bad++;}}
for(const q of no){const x=A(q);if(x&&typeof x==='object'&&pat.test(x.title)){console.error('OVERTRIGGER',q,x.title);bad++;}}
if(bad)throw new Error('patrol63 failed '+bad);console.log('ok');
